package net.civeira.phylax.features.access.trustedclient.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class ClientUriVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property client uri of trusted client ")
  void test_client_uri_v_o_builder() {
    Assertions.assertFalse(ClientUriVO.nullValue().getClientUri().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(ClientUriVO.tryFrom(null).getClientUri().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", ClientUriVO.from("one").getClientUri().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> ClientUriVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", ClientUriVO.from("one").toString());
  }
}
